// Consolidar Contenido — v8
// Unifica texto / audio / imagen / PDF en UNA string antes del agente.
// El ramo Meta vive ahora en un workflow separado (parked), asi que el
// origen siempre es el chat trigger.
// Lee la salida de IA en CUALQUIER formato: node nativo Google Gemini
// (json.content.parts[0].text o json.content string) o HTTP Request
// (json.candidates[0].content.parts[0].text). Nunca devuelve
// contenido_procesado vacio.

const item = $input.first().json;
const origen = $('When chat message received').first().json;
const leyenda = (origen.chatInput || '').trim();

const salidaIA =
     item?.content?.parts?.[0]?.text
  ?? item?.candidates?.[0]?.content?.parts?.[0]?.text
  ?? (typeof item?.content === 'string' ? item.content : undefined);

let tipo = 'texto';
let contenido = '';

if (typeof salidaIA === 'string' && salidaIA.trim() !== '') {
  const s = salidaIA.trim();

  if (s.startsWith('[COMPROBANTE]')) {
    tipo = 'imagen';
    contenido = '[El huesped envio un COMPROBANTE DE TRANSFERENCIA. Datos extraidos:]\n'
              + s.replace('[COMPROBANTE]', '').trim();

  } else if (s.startsWith('[NO_ES_COMPROBANTE]')) {
    tipo = 'imagen';
    contenido = '[El huesped envio una imagen que NO es un comprobante de pago.]\n'
              + s.replace('[NO_ES_COMPROBANTE]', '').trim();

  } else if (s.startsWith('[ILEGIBLE]')) {
    tipo = 'imagen';
    contenido = '[El huesped envio una imagen ILEGIBLE o borrosa.]';

  } else if (s.includes('[AUDIO_INAUDIBLE]')) {
    tipo = 'audio';
    contenido = '[El huesped envio un audio que no se pudo entender.]';

  } else {
    tipo = 'audio';
    contenido = '[El huesped envio un audio. Transcripcion:] ' + s;
  }

} else if (typeof item?.text === 'string' && item.text.trim() !== '') {
  tipo = 'pdf';
  contenido = '[El huesped envio un documento PDF. Contenido extraido:]\n'
            + item.text.trim().slice(0, 4000);

} else if (item?.contenido_procesado === '[FORMATO_NO_SOPORTADO]') {
  tipo = 'no_soportado';
  contenido = '[FORMATO_NO_SOPORTADO]';

} else {
  tipo = 'texto';
  contenido = leyenda;
}

if (tipo !== 'texto' && tipo !== 'no_soportado' && leyenda) {
  contenido += '\n\n[Mensaje que acompanaba el archivo:] ' + leyenda;
}

if (!contenido || contenido.trim() === '') {
  contenido = leyenda || '[El huesped envio un mensaje que no se pudo procesar.]';
}

return [{ json: { ...origen, tipo_mensaje: tipo, contenido_procesado: contenido } }];
